mapper.select:
SELECT id, shop_id, item_name, category_id, is_seasonal
FROM items
WHERE id = #{id}

mapper.update:
UPDATE items
SET item_name = #{itemName},
    category_id = #{categoryId},
    is_seasonal = #{isSeasonal}
WHERE id = #{id}

mapper.delete:
DELETE FROM items
WHERE id = #{id}
  AND NOT EXISTS (SELECT 1 FROM records WHERE records.item_id = #{id})
